/* @lc app=leetcode id=3525 lang=kotlin */ class Solution { fun mg(a: IntArray, b: IntArray, k: Int): IntArray = IntArray(k + 1).also { r -> r[0] = a[0] * b[0] % k }.also { r -> (0 until k).forEach { x -> r[1 + x] += a[1 + x] }.let { (0 until k).forEach { y -> r[1 + (a[0] * y) % k] += b[1 + y] } } } fun lf(v: Int, k: Int): IntArray = IntArray(k + 1).also { it[0] = v % k }.also { it[1 + v % k]++ } fun id(k: Int): IntArray = IntArray(k + 1).also { it[0] = 1 % k } fun resultArray(nums: IntArray, k: Int, queries: Array<IntArray>): IntArray = generateSequence(1) { it * 2 }.first { it >= nums.size }.let { sz -> Array(2 * sz) { id(k) }.also { t -> nums.indices.forEach { t[sz + it] = lf(nums[it], k) } }.also { t -> (sz - 1 downTo 1).forEach { t[it] = mg(t[2 * it], t[2 * it + 1], k) } }.let { t -> queries.map { (idx, value, start, x) -> t.set(sz + idx, lf(value, k)).let { generateSequence((sz + idx) / 2) { it / 2 }.takeWhile { it >= 1 }.forEach { i -> t[i] = mg(t[2 * i], t[2 * i + 1], k) } }.let { generateSequence(Triple(start + sz, 2 * sz, id(k) to id(k))) { (lo, hi, p) -> if (lo >= hi) null else (if (lo % 2 == 1) mg(p.first, t[lo], k) else p.first).let { a2 -> (if (hi % 2 == 1) mg(t[hi - 1], p.second, k) else p.second).let { b2 -> Triple((lo + lo % 2) / 2, (hi - hi % 2) / 2, a2 to b2) } } }.last().third.let { (a, b) -> mg(a, b, k)[1 + x] } } }.toIntArray() } } }